// ponytail: in-scope docs are fixed; add a path here to widen the audit
const VAULT = "My vault";
return ["Claude/Skills MOC.md", "Claude/Claude MOC.md", "Claude/INDEX.md", "02 - Personal IT/01 - Projects/Homelab/00-homelab-index.md", "Claude/memory/MEMORY.md"].map(p => ({ json: { path: VAULT + '/' + p, rel: p } }));

// brain-drift mechanical checks. files: vault-relative paths (no trailing '/'); docs: {path: text}.
// Returns [{doc, kind, detail}]. Pure — embedded verbatim in the n8n Code node.
function brainDriftChecks(files, docs) {
  const SKILLS_MOC = 'Claude/Skills MOC.md', CLAUDE_MOC = 'Claude/Claude MOC.md', INDEX = 'Claude/INDEX.md';
  const HL = '02 - Personal IT/01 - Projects/Homelab/', HL_INDEX = HL + '00-homelab-index.md', MEM = 'Claude/memory/MEMORY.md';
  const fileSet = new Set(files), lower = files.map(f => f.toLowerCase());
  const dirOf = p => p.slice(0, p.lastIndexOf('/') + 1);
  const norm = p => { const out = []; for (const s of p.split('/')) s === '..' ? out.pop() : (s && s !== '.' && out.push(s)); return out.join('/'); };
  const findings = [];
  const add = (doc, kind, detail) => findings.push({ doc, kind, detail });

  // Obsidian resolution: exact path, else path-suffix, else basename; '.md' optional. Returns resolved path or null.
  function resolveWiki(target) {
    const t = target.toLowerCase(), cands = /\.[a-z0-9]{1,5}$/.test(t) ? [t] : [t + '.md', t];
    for (const c of cands) {
      const i = lower.findIndex(f => f === c || f.endsWith('/' + c));
      if (i >= 0) return files[i];
    }
    return null;
  }
  // every outgoing link of a doc, resolved: [{raw, path|null}]
  function links(docPath) {
    const text = (docs[docPath] || '').replace(/```[\s\S]*?```/g, '').replace(/`[^`\n]*`/g, '');
    const out = [];
    for (const m of text.matchAll(/!?\[\[([^\]|#^]*)[^\]]*\]\]/g)) {
      if (!m[1].trim()) continue; // [[#heading]] — same-file anchor
      out.push({ raw: m[1].trim(), path: resolveWiki(m[1].trim()) });
    }
    for (const m of text.matchAll(/\]\(([^)\s]+)\)/g)) {
      const href = m[1];
      if (/^[a-z]+:|^#/i.test(href)) continue; // external URL or anchor
      let p; try { p = decodeURIComponent(href.split('#')[0]); } catch (e) { p = href.split('#')[0]; }
      const rel = norm(dirOf(docPath) + p);
      out.push({ raw: href, path: fileSet.has(rel) ? rel : (fileSet.has(norm(p)) ? norm(p) : resolveWiki(p)) });
    }
    return out;
  }

  const linked = {};
  for (const d of Object.keys(docs)) {
    linked[d] = links(d);
    for (const l of linked[d]) if (!l.path) add(d, 'broken link', l.raw);
  }
  const targets = d => new Set((linked[d] || []).map(l => l.path).filter(Boolean));

  // Skills MOC: one entry per skill dir that has a SKILL.md (synced/ lives one level deeper, so it's excluded)
  if (docs[SKILLS_MOC] !== undefined) {
    const t = targets(SKILLS_MOC);
    for (const f of files) if (/^Claude\/skills\/[^/]+\/SKILL\.md$/.test(f) && !t.has(f)) add(SKILLS_MOC, 'skill not listed', f.split('/')[2]);
  }

  // Claude MOC + INDEX together: top-level knowledge/identity notes and research topics, linked from at least one
  if (docs[CLAUDE_MOC] !== undefined || docs[INDEX] !== undefined) {
    const t = new Set([...targets(CLAUDE_MOC), ...targets(INDEX)]);
    for (const f of files) if (/^Claude\/(knowledge|identity|identity\/odysseus)\/[^/]+\.md$/.test(f) && !t.has(f)) add(CLAUDE_MOC, 'not linked from Claude MOC or INDEX', f);
    const topics = new Set(files.map(f => (f.match(/^(Claude\/knowledge\/research\/[^/]+)\//) || [])[1]).filter(Boolean));
    for (const topic of topics) if (![...t].some(p => p.startsWith(topic + '/'))) add(CLAUDE_MOC, 'research topic not linked', topic);
  }

  // Homelab index: every Homelab/*.md and Homelab/docs/*.md
  if (docs[HL_INDEX] !== undefined) {
    const t = targets(HL_INDEX);
    for (const f of files) {
      if (f === HL_INDEX || !f.startsWith(HL) || !f.endsWith('.md')) continue;
      const rest = f.slice(HL.length);
      if ((!rest.includes('/') || /^docs\/[^/]+$/.test(rest)) && !t.has(f)) add(HL_INDEX, 'note not in index', rest);
    }
  }

  // MEMORY.md: every memory note indexed (broken index lines are already caught above as broken links)
  if (docs[MEM] !== undefined) {
    const t = targets(MEM);
    for (const f of files) if (/^Claude\/memory\/[^/]+\.md$/.test(f) && f !== MEM && !t.has(f)) add(MEM, 'memory note not indexed', f.split('/').pop());
  }
  return findings;
}


const PREFIX = '/remote.php/webdav/' + "My vault/";
const dec = p => { try { return decodeURIComponent(p); } catch (e) { return p; } };
// PROPFIND multistatus: collections' hrefs end in '/', files' don't
const xml = String($('List vault').first().json.data || '');
const files = [...xml.matchAll(/<d:href>([^<]+)<\/d:href>/g)].map(m => dec(m[1]))
  .filter(p => p.startsWith(PREFIX) && !p.endsWith('/')).map(p => p.slice(PREFIX.length));
const paths = $('Doc paths').all().map(i => i.json.rel);
const docs = {};
$input.all().forEach((item, i) => { docs[paths[i]] = String(item.json.data || ''); });
const findings = brainDriftChecks(files, docs);
// Nextcloud may refuse Depth:infinity and return one level; every check would then pass vacuously
if (!files.some(f => f.includes('/'))) findings.unshift({ doc: '(listing)', kind: 'vault listing not recursive', detail: files.length + ' files, all top-level — checks unreliable' });
const memIndex = (docs['Claude/memory/MEMORY.md'] || '').split('\n').filter(l => l.startsWith('- ['));
const ssot = String($('Get SSOT').first().json.data || '');
return [{ json: { findings, fileCount: files.length, llmUser: ssot ? 'THALES-SSOT.md (authoritative):\n\n' + ssot + '\n\n---\nMEMORY.md index lines:\n\n' + memIndex.join('\n') : '' } }];

const c = $('Checks').first().json;
const findings = [...c.findings];
let llm = 'LLM check skipped (no SSOT or no OpenRouter reply)';
try {
  const raw = $input.first().json.choices[0].message.content.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
  const arr = JSON.parse(raw);
  for (const x of arr) findings.push({ doc: 'Claude/memory/MEMORY.md', kind: 'contradicts SSOT', detail: `${x.file}: "${x.claim}" — SSOT: "${x.ssot_says}"` });
  llm = `LLM check: ${arr.length} contradiction(s)`;
} catch (e) {}
const date = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' });
const rel = `Claude/_drift/brain-drift-${date}.md`;
const byDoc = {};
for (const f of findings) (byDoc[f.doc] ??= []).push(f);
const note = [
  '---', 'type: drift-report', `created: ${date}`, 'source: n8n brain-drift (thalesBrainDrft1)', '---',
  `# Brain drift — ${date}`, '',
  `Proposals only — nothing was edited. ${c.fileCount} vault files scanned. ${llm}. Per [[ssot-over-memory]], the SSOT wins a contradiction. Delete this note once handled.`, '',
  ...Object.entries(byDoc).flatMap(([doc, fs]) => [`## [[${doc.replace(/\.md$/, '')}]]`, ...fs.map(f => `- [ ] **${f.kind}**: ${f.detail}`), '']),
].join('\n');
const message = findings.length
  ? `**brain-drift**: ${findings.length} finding(s) → \`${rel}\` (${llm})`
  : `**brain-drift**: clean — ${c.fileCount} files, 5 docs. ${llm}`;
return [{ json: { count: findings.length, note, message, path: `_drift/brain-drift-${date}.md` } }];  // n8n-brain's /_drift share mount = My vault/Claude/_drift
